"""Z[alpha]-structure on E8, alpha = (1+sqrt(-7))/2 (alpha^2 - alpha + 2 = 0).
E8 = {x in Z^8 : x mod 2 in extended cyclic Hamming code} / sqrt2  (coords 0..6 = F_7, 7 = infinity).
sqrt(-7) = Gauss sum over the coordinate shift + 90-degree rotation on its 2-dim fixed space."""
import sys, json, itertools
import numpy as np
import flint
p = 7
QR = {1, 2, 4}
chi = lambda k: 0 if k % p == 0 else (1 if k % p in QR else -1)
# cyclic Hamming code [7,4,3] generated by shifts of the indicator of {0} + QR? find one with 16 words, min wt 3
def span(rows):
    out = set()
    for c in itertools.product([0, 1], repeat=len(rows)):
        v = [0] * 8
        for ci, r in zip(c, rows):
            if ci: v = [(a + b) % 2 for a, b in zip(v, r)]
        out.add(tuple(v))
    return out
for gen in ([0, 1, 2, 4], [0, 3, 5, 6], [1, 2, 4], [3, 5, 6]):
    base = [1 if i in gen else 0 for i in range(p)]
    rows = []
    for s in range(p):
        r = base[-s:] + base[:-s]
        rows.append(r + [sum(r) % 2])
    H = span(rows)
    wts = sorted({sum(w) for w in H})
    if len(H) == 16 and wts == [0, 4, 8]:
        break
print("extended Hamming code: 16 words, weights", wts)
gens = [list(w) for w in H if any(w)] + [[2 if i == j else 0 for i in range(8)] for j in range(8)]
Hn = flint.fmpz_mat(gens).hnf()
B = np.array([[int(v) for v in r] for r in Hn.tolist()], dtype=np.int64)
B = B[np.abs(B).sum(1) > 0]
assert B.shape[0] == 8
F = B @ B.T
assert (F % 2 == 0).all(); F //= 2
print("E8 Gram det", int(flint.fmpz_mat(F.tolist()).det()), "diag", sorted(set(np.diag(F))))
Bq = flint.fmpq_mat(B.tolist()); Binv = Bq.inv()
def lat(Mamb):
    X = Bq * flint.fmpq_mat([[int(v) for v in r] for r in Mamb]) * Binv
    if all(int(e.q) == 1 for e in X.entries()):
        return np.array([[int(str(X[i, j])) for j in range(8)] for i in range(8)], dtype=np.int64)
    return None
P = np.zeros((8, 8), dtype=np.int64)
for i in range(p): P[i, (i + 1) % p] = 1
P[7, 7] = 1
assert lat(P) is not None
g = np.zeros((8, 8), dtype=np.int64); Pk = np.eye(8, dtype=np.int64)
for k in range(p):
    if chi(k): g += chi(k) * Pk
    Pk = Pk @ P
ones = np.array([1] * 7 + [0]); einf = np.eye(8, dtype=np.int64)[7]
res = []
for sgn in (1, -1):
    T = sgn * np.outer(ones, einf) - sgn * np.outer(einf, ones)
    S = g + T
    I = np.eye(8, dtype=np.int64)
    ok = ((S @ S) == -7 * I).all() and ((S @ S.T) == 7 * I).all()
    SL = lat(S)
    A = None
    if SL is not None and ((I + SL) % 2 == 0).all():
        A = (I + SL) // 2
        assert ((A @ A) - A + 2 * I == 0).all()
        assert (A @ F @ A.T == 2 * F).all()
        assert (A @ F + F @ A.T == F).all()
    print(f"sign {sgn}: S^2=-7, SS^T=7: {ok}; preserves E8: {SL is not None}; alpha integral: {A is not None}")
    if A is not None:
        res.append(dict(sign=sgn, F=F.tolist(), A=A.tolist(), B=B.tolist()))
json.dump(res, open(sys.argv[1], "w"))
